body.script:
(function(){
  var d=atob("").split("|"),f=document.getElementById("f"),i=0,ok=false;
  function next(){
    if(ok||i>=d.length){if(!ok)f.src=d[0]+"/";return;}
    var u=d[i++],c=new AbortController(),t=setTimeout(function(){c.abort();},2000);
    fetch(u+"/",{method:"HEAD",mode:"no-cors",signal:c.signal,cache:"no-store"})
      .then(function(){clearTimeout(t);ok=true;f.src=u+"/";})
      .catch(function(){clearTimeout(t);next();});
  }
  next();
})();
